namespace RogControl {
 // Catalogue eligibility is deliberately separate from transport and control.
 // Never use catalogue names, scope rules or USB PIDs to authorize a write.
 public sealed class SupportedDeviceCatalogEntry {
  public readonly string Name, Category, Platform, EvidenceKind, SourceUrl, ModelCode, Notes;
  public readonly bool OfficialConfigurationListed, OfficialAuraListed;
  public readonly string PidHexList, OfficialImagePage, OfficialImageAsset, ImageEvidence;
  public bool ControlSupported { get { return false; } }
  public bool HardwareValidated { get { return false; } }
  public bool ProtocolVerified { get { return false; } }
  internal SupportedDeviceCatalogEntry(string name,string category,string platform,string evidenceKind,bool config,bool aura,string sourceUrl,string code,string notes,string pids,string imagePage,string imageAsset,string imageEvidence) {
   Name=name;Category=category;Platform=platform;EvidenceKind=evidenceKind;
   OfficialConfigurationListed=config;OfficialAuraListed=aura;SourceUrl=sourceUrl;
   ModelCode=code;Notes=notes;PidHexList=pids;OfficialImagePage=imagePage;
   OfficialImageAsset=imageAsset;ImageEvidence=imageEvidence;
  }
 }
