  public const string HandheldSource="https://rog.asus.com/support/faq/1050220/";
  static readonly ReadOnlyCollection<SupportedDeviceCatalogEntry> entries=Create();
  public static ReadOnlyCollection<SupportedDeviceCatalogEntry> Entries { get { return entries; } }
  // Exact informational lookup only. A repeated model code can represent more
  // than one family/year/variant and must never pick a hardware adapter.
  public static SupportedDeviceCatalogEntry[] FindExactName(string name) {
   if(String.IsNullOrWhiteSpace(name))return new SupportedDeviceCatalogEntry[0];
   return entries.Where(e=>String.Equals(e.Name,name.Trim(),StringComparison.OrdinalIgnoreCase)).ToArray();
  }
  public static SupportedDeviceCatalogEntry[] FindModelCode(string code) {
   if(String.IsNullOrWhiteSpace(code))return new SupportedDeviceCatalogEntry[0];
   return entries.Where(e=>!String.IsNullOrEmpty(e.ModelCode)&&String.Equals(e.ModelCode,code.Trim(),StringComparison.OrdinalIgnoreCase)).ToArray();
  }
